def calculate_total(items, tax_rate=0.0):
    """Compute total with tax applied to each item subtotal."""
    subtotal = sum(item.price * item.quantity for item in items)
    tax = subtotal * tax_rate
    return subtotal + tax

class ShoppingCart:
    def __init__(self):
        self.items = []

    def add(self, item):
        self.items.append(item)

    def checkout(self, tax_rate=0.08):
        return calculate_total(self.items, tax_rate)
